import base64,copy,hashlib,io,json,re
VERSION='SM-NATIVE-LEARNER-STIMULUS-IMAGE-20261123-1'
IMAGE_TYPES={'IMAGE_REFERENCE','DIAGRAM_REFERENCE'}
MAX_BYTES=2_000_000
MAX_PIXELS=25_000_000
KEY='ph_learner_image_ref'

def canonical(v):return json.dumps(v,sort_keys=True,ensure_ascii=False,separators=(',',':'),allow_nan=False)
def digest(v):return hashlib.sha256(canonical(v).encode()).hexdigest()
def image_content(stimulus):
 if not isinstance(stimulus,dict) or stimulus.get('stimulus_type') not in IMAGE_TYPES:return None
 content=stimulus.get('content')
 if not isinstance(content,dict):raise ValueError('PH_IMAGE_CONTENT_REQUIRED')
 uri=content.get('uri');pin=content.get('file_sha256')
 if not isinstance(uri,str) or len(uri)>MAX_BYTES*4//3+100 or not re.fullmatch('[0-9a-f]{64}',str(pin or '')):raise ValueError('PH_IMAGE_BOUNDED_URI_AND_HASH_REQUIRED')
 match=re.fullmatch(r'data:(image/png|image/jpeg);base64,([A-Za-z0-9+/]+={0,2})',uri)
 if not match:raise ValueError('PH_IMAGE_EMBEDDED_PNG_JPEG_ONLY')
 try:data=base64.b64decode(match[2],validate=True)
 except Exception:raise ValueError('PH_IMAGE_BASE64_INVALID') from None
 if not 0<len(data)<=MAX_BYTES or hashlib.sha256(data).hexdigest()!=pin:raise ValueError('PH_IMAGE_BYTES_HASH_MISMATCH')
 from PIL import Image
 try:
  with Image.open(io.BytesIO(data)) as image:
   expected='PNG' if match[1]=='image/png' else 'JPEG'
   if image.format!=expected or image.width<1 or image.height<1 or image.width*image.height>MAX_PIXELS:raise ValueError('PH_IMAGE_DIMENSIONS_OR_FORMAT_INVALID')
   image.verify()
 except Exception as e:raise ValueError('PH_IMAGE_DECODE_INVALID:'+type(e).__name__) from None
 if content.get('mime_type') not in (None,match[1]):raise ValueError('PH_IMAGE_MIME_CONFLICT')
 return {'uri':uri,'file_sha256':pin,'mime_type':match[1]}

def image_ref(stimulus):
 parsed=image_content(stimulus)
 if parsed is None:return None
 unsigned={k:v for k,v in stimulus.items() if k!='stimulus_checksum_sha256'}
 if stimulus.get('stimulus_checksum_sha256')!=digest(unsigned):raise ValueError('PH_IMAGE_STIMULUS_CHECKSUM_MISMATCH')
 return {'version':VERSION,'stimulus_id':stimulus['stimulus_id'],'stimulus_version_id':stimulus['stimulus_version_id'],'stimulus_checksum_sha256':stimulus['stimulus_checksum_sha256'],'media_sha256':parsed['file_sha256'],'mime_type':parsed['mime_type']}

def validated_ref(ref,content=None):
