def _projection(question, stimuli):
    from ph_learner_media_v1 import project
    base = _ph_image_prior_projection(question, stimuli)
    try:
        return project(base, question, stimuli)
    except (ValueError, TypeError, KeyError) as exc:
        # Native admission records contract failures durably before immutable
        # release/version writes. Preserve that existing retry/rejection seam.
        raise question_contracts.QuestionContractError('LEARNER_IMAGE_UNSUPPORTED: ' + str(exc)) from exc

def effective_projection(stored, content):
    from ph_learner_media_v1 import preserve_ref
    return preserve_ref(stored, _ph_image_prior_effective_projection(stored, content), content)

def _semantic_content_errors(questions, stimuli, schema_version=SCHEMA_VERSION):
    from ph_learner_media_v1 import image_ref
    errors = _ph_image_prior_semantic_content_errors(questions, stimuli, schema_version)
    for index, stimulus in enumerate(stimuli or []):
        try:
            image_ref(stimulus)
        except (ValueError, TypeError, KeyError) as exc:
            errors.append({'code': 'LEARNER_IMAGE_UNSUPPORTED', 'path': 'payload.stimuli[%s]' % index,
                           'message': str(exc), 'retryable': False})
    return errors

