def pinned_question(session_row, qid, current_row):
    from ph_learner_media_v1 import KEY, config, validated_ref
    result = _ph_image_prior_pinned_question(session_row, qid, current_row)
    ref = config(dict(result).get('answer_config')).get(KEY)
    if ref is None:
        return result
    return {**dict(result), KEY: validated_ref(ref)}

